/**
 * 🔹 Full Library Portal Backend + Frontend Connection
 * Backend: Node.js + Express + MySQL
 * Frontend: তোমার index.html ফাইল
 */

const express = require("express");
const bodyParser = require("body-parser");
const mysql = require("mysql2");
const path = require("path");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(bodyParser.json());
app.use(express.static(__dirname)); // frontend serve করবে

// ✅ Database Connection
const db = mysql.createConnection({
  host: "localhost",
  user: "root", // তোমার MySQL username
  password: "", // তোমার MySQL password
  database: "library_portal"
});

db.connect((err) => {
  if (err) {
    console.error("❌ Database connection failed:", err);
  } else {
    console.log("✅ Connected to MySQL Database");
  }
});

// ========================
//  FRONTEND SERVE SECTION
// ========================
app.get("/", (req, res) => {
  res.sendFile(path.join(__dirname, "index.html"));
});

// ========================
//  BACKEND API SECTION
// ========================

// 🧾 Student Login API
app.post("/student-login", (req, res) => {
  const { studentId, password } = req.body;
  const query = "SELECT * FROM students WHERE student_id = ? AND password = ?";
  db.query(query, [studentId, password], (err, results) => {
    if (err) {
      console.error("Error during student login:", err);
      return res.status(500).json({ message: "Database error" });
    }
    if (results.length > 0) {
      res.json({ message: "✅ Student Login Successful!" });
    } else {
      res.status(401).json({ message: "❌ Invalid Student ID or Password" });
    }
  });
});

// 🧾 Admin Login API
app.post("/admin-login", (req, res) => {
  const { adminId, password } = req.body;
  const query = "SELECT * FROM admins WHERE admin_id = ? AND password = ?";
  db.query(query, [adminId, password], (err, results) => {
    if (err) {
      console.error("Error during admin login:", err);
      return res.status(500).json({ message: "Database error" });
    }
    if (results.length > 0) {
      res.json({ message: "✅ Admin Login Successful!" });
    } else {
      res.status(401).json({ message: "❌ Invalid Admin ID or Password" });
    }
  });
});

// ========================
//  SERVER START
// ========================
const PORT = 5000;
app.listen(PORT, () => {
  console.log(`🚀 Server running at http://localhost:${PORT}`);
});
